// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: amount of ETH sent (could be zero or nonzero) and the sender address
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount within reasonable bounds (but wide)
        amount = bound(amount, 0, 1 ether);
        // sender must be a nonzero address
        vm.assume(sender != address(0));

        // fund the sender so they can send the amount
        vm.deal(sender, amount);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // perform the receive() by making a plain value transfer from sender
        vm.prank(sender);
        // use low-level call to send ETH which triggers receive()
        (bool ok, ) = address(c).call{value: amount}("");
        // successful call or not is allowed; we observe final state via getter

        uint256 after = c.depositsCount();

        // GENERAL RULE assertion: for ANY admissible input, a call that sends ETH (amount > 0)
        // should increment depositsCount by exactly 1 on the correct contract.
        // We assert only when amount > 0, because sending zero value may be considered no deposit.
        if (amount > 0) {
            assertTrue(after == before + 1);
        } else {
            // if amount == 0, we require depositsCount unchanged
            assertTrue(after == before);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount within reasonable bounds (but wide)
        amount = bound(amount, 0, 1 ether);
        // ensure sender has ETH to send
        vm.deal(sender, amount);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // perform the payable send to trigger receive()
        bool ok;
        vm.prank(sender);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded and amount > 0, reference implementation must have incremented depositsCount by 1.
        // This single assertion reads c's public getter and distinguishes the mutant (which reverts and thus ok==false
        // or prevents increment).
        if (amount > 0 && ok) {
            // require that depositsCount increased by exactly 1
            assertTrue(c.depositsCount() == before + 1);
        } else {
            // If amount == 0 or the call reverted, then depositsCount should be unchanged
            assertTrue(c.depositsCount() == before);
        }
    }
}

