pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and amount. amount must be within balanceable range; keep wide but nonzero.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a reasonable domain: 1 .. 1e30 to avoid absurd overflows but allow wide search
        amount = bound(amount, 1, 1e30);
        // ensure the sender has funds to send
        vm.deal(sender, amount);

        // act as the sender and perform a plain transfer that triggers receive()
        vm.prank(sender);
        // send ETH via low-level call to trigger receive()
        (bool ok, ) = address(c).call{value: amount}("");

        // For the correct contract: if the call succeeded, depositsCount must have increased by 1.
        // We only assert the universal property in terms of observable public getter depositsCount.
        // Query the public getter
        uint256 count = c.depositsCount();

        // If the call succeeded, then reference implementation guarantees depositsCount >= 1
        // (since setUp starts with 0 and each successful receive increments by exactly 1).
        // Use a single assertion over c's public getter state that distinguishes mutant on some input.
        if (ok) {
            assertTrue(count == 1);
        } else {
            // if call reverted, depositsCount must remain 0
            assertTrue(count == 0);
        }
    }
