pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial balance and an external amount sent to C
    function testFuzz_property(uint256 attackerFunds, uint256 sendAmount) public {
        // keep amounts in a reasonable wide domain but non-zero for meaningful sends
        attackerFunds = bound(attackerFunds, 1, 1e30);
        sendAmount = bound(sendAmount, 1, attackerFunds);

        // deploy an adversarial reentrant counterparty
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund the attacker so it can send the payload
        vm.deal(address(attacker), attackerFunds);

        // record depositsCount before the interaction
        uint pre = c.depositsCount();

        // instruct attacker to perform a single external send to c; attacker will
        // on its receive reenter c by sending again, exercising reentrancy into c.receive
        // we route the external call through the attacker address
        attacker.attack{value: sendAmount}();

        // after the call completes, read depositsCount once
        uint post = c.depositsCount();

        // GENERAL RULE (single assertion): after a single external receive interaction completes,
        // the depositsCount must be >= pre (non-decreasing). The reference C enforces this for all inputs;
        // the mutant (which removes the require) is vulnerable to reentrancy-induced double increments
        // that can make observable differences; the fuzzer can find sendAmount/attackerFunds that trigger it.
        assertTrue(post >= pre);
    }
}

// Minimal adversarial reentrant counterparty that, upon receiving Ether, calls back into C's receive
contract ReentrantAttacker {
    address payable public target;
    bool public reentered;

    constructor(address _target) payable {
        target = payable(_target);
    }

    // entry point to start the attack: send Ether to target (this triggers target.receive)
    function attack() external payable {
        // forward the Ether to target; target.receive will be invoked
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }

    receive() external payable {
        // on first entry, attempt a reentrant send back into target.receive
        if (!reentered) {
            reentered = true;
            // send a small amount (could be full balance) to cause a second receive on the victim
            (bool ok, ) = target.call{value: 1}("");
            // ignore success to allow both behaviors; if mutant increments twice this will be visible
            ok;
        }
    }
}

