pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an attacker seed amount and an attacker starting balance
    function testFuzz_property(uint256 attackerSeed, uint256 attackerBalance) public {
        // keep attackerBalance reasonable and non-zero so the attacker can send value
        attackerBalance = bound(attackerBalance, 1, 1 ether);
        // attackerSeed controls how many reentrant calls attacker will attempt (keep within small bounds)
        uint256 tries = bound(attackerSeed, 1, 5);

        // deploy attacker helper with reentrancy behavior: its receive will reenter c.receive via sending value back
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), tries);

        // fund attacker
        vm.deal(address(attacker), attackerBalance);

        // record old depositsCount
        uint old = c.depositsCount();

        // perform a single top-level send to c from attacker (this will trigger attacker's receive -> reentrancy)
        // note: we must send value to trigger receive
        attacker.attack{value: attackerBalance}();

        // After the top-level call completes, the correct contract C increments depositsCount exactly once per receive call
        // The intended universal property: for any single top-level send, depositsCount == old + 1
        // The mutant that removed the require can be reentered and cause depositsCount > old + 1
        assertTrue(c.depositsCount() == old + 1);
    }
}

// Minimal adversarial helper: on receive, it reenters the target contract by sending a small value back up to `maxReentry` times.
contract ReentrantAttacker {
    address target;
    uint256 maxReentry;
    uint256 reentryCount;

    constructor(address _target, uint256 _maxReentry) payable {
        target = _target;
        maxReentry = _maxReentry;
        reentryCount = 0;
    }

    // entry point used to start the top-level send
    function attack() external payable {
        // perform a single top-level send to target to invoke its receive()
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }

    // when this contract receives funds (from target during its receive), attempt to reenter target up to maxReentry times
    receive() external payable {
        if (reentryCount < maxReentry) {
            reentryCount++;
            // reenter target with a tiny value if we still have balance
            uint256 v = address(this).balance / 2;
            if (v > 0) {
                (bool ok, ) = target.call{value: v}("");
                // ignore ok to allow differing behaviors; reentrancy may revert in some cases
            }
        }
    }
}

