pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(); }

    // fuzzed params: sender and value
    function testFuzz_property(address sender, uint256 value) public {
        // keep domains wide but sensible
        vm.assume(sender != address(0));
        // value should be non-zero to trigger receive
        vm.assume(value > 0 && value <= 1 ether);

        // fund the sender and the attacker helper
        vm.deal(sender, value);
        vm.deal(address(attacker), 1 ether);

        // make attacker target the deployed contract
        attacker.setTarget(address(c));

        // record old depositsCount
        uint before = c.depositsCount();

        // Have the attacker be the msg.sender of the top-level transfer so its receive can reenter
        vm.prank(sender);
        // send value to c but with attacker performing a low-level call into c to trigger reentrancy
        // We instruct the attacker to perform the top-level transfer to c so its receive() will execute
        // with msg.sender == attacker (a contract) only when attacker is the one sending; so instead we
        // have attacker execute the transfer while we slot the EOA as its tx.origin by prank/cheatcodes.
        // Simpler: have attacker perform the transfer while we set tx.origin to sender via prank start.
        vm.startPrank(sender);
        // attacker will do a call to c with value forwarded from sender via address(attacker).call{value:...}()
        // To achieve that, first send ETH to attacker from sender, then have attacker forward to c reentrantly.
        // Transfer funds from sender to attacker
        (bool okSend,) = address(attacker).call{value: value}("");
        require(okSend);
        // stop prank as subsequent calls originate from attacker
        vm.stopPrank();

        // Now let attacker perform a top-level transfer to c; attacker will in its receive reenter c
        // and attempt to call c again causing depositsCount to be incremented twice if unprotected.
        uint beforeBal = address(c).balance;
        attacker.doAttack{value: value}();

        // exactly one assertion: after this single top-level attacker's transfer, depositsCount should be before+1
        // In the reference contract, the require prevents reentrant double-increment and ensures depositsCount == before+1
        // The mutant (without the require) can lead to depositsCount > before+1 for some attacker behavior/values
        assertTrue(c.depositsCount() == before + 1);

        // sanity: ensure balance moved
        assertTrue(address(c).balance >= beforeBal);
    }
}

// Minimal reentrant attacker: when receiving ETH it will call back into C to trigger a second increment
contract Attacker {
    address public target;
    bool public reentered;

    function setTarget(address _t) public { target = _t; }

    // entry used by test to perform the top-level transfer into C
    function doAttack() public payable {
        // send value to target (this is the top-level receive invocation)
        (bool ok,) = payable(target).call{value: msg.value}("");
        require(ok);
    }

    receive() external payable {
        // on first receive from C, attempt to reenter C via a low-level call
        if (!reentered) {
            reentered = true;
            // call target again during the same top-level invocation to cause a second increment if unchecked
            (bool ok,) = payable(target).call{value: 0}("");
            // ignore ok
            ok;
        }
    }
}

