pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker address (as the EOA that will deploy the attacker) and an amount to send
    function testFuzz_property(address attackerEOA, uint256 amount) public {
        // Keep domain wide but sensible: non-zero amount and a non-zero address for the attacker deployer
        vm.assume(attackerEOA != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy an adversarial reentrant contract from attackerEOA
        vm.prank(attackerEOA);
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund the attacker and the EOA so it can send ETH
        vm.deal(address(attacker), amount * 2);
        vm.deal(attackerEOA, amount * 2);

        // Record depositsCount before the top-level call
        uint before = c.depositsCount();

        // Have the attacker send ETH to c, triggering receive(). The attacker will attempt to re-enter during the receive.
        // Use prank from attacker so msg.sender for the top-level call is the attacker contract's address.
        vm.prank(address(attacker));
        (bool ok, ) = address(c).call{value: amount}("");
        // We do not assume the call must succeed; both reference and mutant must allow the top-level invocation to complete or revert.
        // After the top-level call completes (whether success or revert), observe depositsCount.

        uint after = c.depositsCount();

        // The universal property (one assertion): for every admissible input, the reference C ensures depositsCount == before + 1.
        // This assertion is expected to hold for the reference contract for all inputs; the mutant (without the require) can be
        // exploited by ReentrantAttacker to make depositsCount > before + 1, causing this assertTrue to fail.
        assertTrue(after == before + 1);
    }
}

// Minimal adversarial reentrant helper. During its receive, it will call back into C to attempt a second deposit.
contract ReentrantAttacker {
    C immutable target;
    bool reentered;

    constructor(address _target) payable {
        target = C(_target);
    }

    // When receiving ETH from sending to C, this contract will try to call C again (re-enter) once.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // call target with some small value to re-enter its receive
            // send 0 value so this is a top-level call into receive again (if fallback/receive path allows)
            // Use low-level call to ensure we target receive
            targetAddressCall(address(target), 0);
        }
    }

    // helper to invoke a plain call to target with given value
    function targetAddressCall(address _t, uint256 v) internal {
        // low-level call to trigger receive/fallback
        (bool s, ) = _t.call{value: v}("");
        // ignore return
        s;
    }
}

