pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender address and amount of ETH to send
    function testFuzz_property(address sender, uint256 amount) public {
        // keep domain wide but sensible: amount must be > 0 and fit in contract balance affordance
        vm.assume(amount > 0);
        // fund the sender so they can send the amount
        vm.deal(sender, amount);

        uint256 before = c.depositsCount();

        // perform the external payable call to receive()
        vm.prank(sender);
        // send value; call will either succeed or revert
        (bool ok, ) = address(c).call{value: amount}("");

        uint256 after = c.depositsCount();

        // General rule: for any admissible input (any sender and any amount > 0),
        // the reference increments depositsCount by exactly 1 when receive() succeeds.
        // We assert that either the call reverted (ok == false) OR depositsCount increased by 1.
        // The buggy mutant inverts the require and will cause the call to revert for all normal arithmetic
        // inputs, so there exist inputs where the mutant fails this property (i.e., ok == true and after == before + 1).
        // The single assertion reads c's public getter depositsCount() and the call success flag.
        assertTrue(ok == false || after == before + 1);
    }
}

