contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payer, uint256 amount) public {
        // keep amount wide but require nonzero payment because receive only runs on value > 0
        vm.assume(amount > 0);
