import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz a payment amount; the rule: after calling receive with a given msg.value, depositsCount in the reference
    // must be >= previous depositsCount and must only increase when the call succeeds. The mutant that increments
    // before the require can make depositsCount increase even when the check would have failed for some values.
    function testFuzz_property(uint256 amount) public {
        // keep amount within payable ranges but wide
        amount = bound(amount, 0, 1 ether);

