        // read after
        uint256 after = c.depositsCount();

        // General property (single assert): For the correct contract, a successful receive increments depositsCount by exactly 1,
        // and a failed receive does not change depositsCount. We observe success via the low-level call return `ok` and
        // assert the corresponding relationship holds.
        assertTrue(ok ? (after == before + 1) : (after == before));
