pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount sent to receive; the adversarial counterparty is a callee that reverts on fallback
    function testFuzz_property(uint256 amount) public {
        // keep amount in reasonable range (but wide)
        amount = bound(amount, 0, 1 ether);

        // deploy a reverter which will be the target of sendMoney if used, but here we need a failing external party
        Reverter r = new Reverter();

        // Fund an attacker EOA to send the payment
        address sender = address(0xCAFE);
        vm.deal(sender, amount);

        // Ensure depositsCount initial is 0
        uint256 before = c.depositsCount();

        // Make the call to receive from the attacker
        vm.prank(sender);
        // call receive with value 'amount'
        (bool ok, ) = address(c).call{value: amount}("");

        // After the call, for the correct contract the invariant holds:
        // depositsCount increased only if the receive succeeded; if receive failed, depositsCount == before.
        // We assert that depositsCount is either unchanged (on failure) or >= before (on success).
        uint256 afterCount = c.depositsCount();
        bool invariant = (ok && afterCount >= before) || (!ok && afterCount == before);

        assertTrue(invariant);
    }
}

contract Reverter {
    fallback() external payable { revert("revert"); }
