pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz over an amount > 0 and choose whether the adversary will revert on receive
    function testFuzz_property(uint256 amount, bool willRevert) public {
        // keep amount within reasonable bounds (not exceeding address(this) balance)
        amount = bound(amount, 0, 1 ether);
        vm.deal(address(this), 1 ether);

        // Deploy adversarial helper that either accepts or reverts on receive
        Adversary adv = new Adversary(willRevert);

        // Fund C so it has balance to attempt forwarding
        // Use owner (setUp deployer) to send ether into C via receive()
        vm.prank(address(this));
        (bool s,) = address(c).call{value: amount}("");
        require(s);

        // Record balance before sendMoney
        uint256 before = address(c).balance;

        // Owner calls sendMoney to instruct C to forward `amount` to adversary
        // caller is owner (deployer), so no need to prank; call normally
        // we limit amount to be at most before so the transfer/send attempt is meaningful
        amount = bound(amount, 0, before);

        bool callOk;
        try c.sendMoney(address(adv), amount) {
            callOk = true;
        } catch {
            callOk = false;
        }

        // After the call, the correct contract (using transfer) would either succeed and reduce C's balance by amount
        // or revert the whole call; in either case, there is no silent acceptance of a failed send that leaves C's balance unchanged while call returns success.
        // The mutant using .send may return false and allow sendMoney to succeed while leaving C's balance unchanged.
        // We assert that either the call reverted (callOk==false) or C's balance decreased by exactly amount.
        // This reads c's actual behavior (address(c).balance) and is always true for reference but can be false for the mutant.
        assertTrue(!callOk || address(c).balance == before - amount);
    }
}

// Adversarial helper: either accept ether or revert on receive
contract Adversary {
    bool public willRevert;
    constructor(bool _willRevert) payable {
        willRevert = _willRevert;
    }
    receive() external payable {
        if (willRevert) revert("reject");
        // otherwise accept
    }
}

