pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - uint128 amount: the amount to send through sendMoney and later attempt to withdraw
    // - bool attackerReverts: whether the helper should revert on receiving funds
    function testFuzz_property(uint128 amount, bool attackerReverts) public {
        // keep amount wide but not exceeding a sane maximum to avoid overflow when vm.deal
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        // Deploy adversarial helper that either accepts or reverts on receive
        AttackerHelper helper = new AttackerHelper(attackerReverts);

        // Fund contract C with amt so sendMoney has balance to forward
        // Make the test actor the owner (deployer) — setUp deployed c so address(this) is owner
        vm.deal(address(this), amt);

        // Ensure c has the funds
        c.sendMoney{value: 0}(address(0), 0); // harmless call to exercise gas; not required
        // Directly send funds to C via payable call
        (bool ok1, ) = address(c).call{value: amt}("");
        require(ok1, "funding c failed");

        // Now attempt to forward amt to helper via sendMoney
        // If helper reverts on receive, the reference's behavior ensures sendMoney (using low-level call) will bubble/revert
        // We capture whether sendMoney reverts or not via try/catch
        bool sendSucceeded;
        try c.sendMoney(address(helper), amt) {
            sendSucceeded = true;
        } catch {
            sendSucceeded = false;
        }

        // After the sendMoney attempt, the owner should always be able to withdraw up to the current c balance using withdraw(uint)
        // We record the balance before withdraw call
        uint256 balBefore = address(c).balance;

        // Try to withdraw the whole balance via withdraw(uint) and observe whether it reverts/succeeds
        bool withdrawSucceeded;
        try c.withdraw(balBefore) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // General rule to assert: The reference C (using transfer in withdraw) always allows the owner to withdraw the contract balance (withdraw succeeds) for every admissible input.
        // The mutant (which uses .send with require on the bool) fails for some inputs where withdraw would return false and thus revert; we make a single assertion that withdrawSucceeded is true.
        assertTrue(withdrawSucceeded);
    }
}

// Adversarial helper: either accepts ETH or reverts on receive depending on constructor param
contract AttackerHelper {
    bool public doRevert;
    constructor(bool _doRevert) payable { doRevert = _doRevert; }
    receive() external payable {
        if (doRevert) revert("revert on receive");
    }
}

