pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send into contract, and a boolean deciding whether the adversary will reject incoming Ether
    function testFuzz_property(uint256 funding, bool adversaryRejects) public {
        // keep funding in a reasonable range but wide
        funding = bound(funding, 0, 1 ether);

        // deploy adversarial recipient whose receive either accepts or reverts based on adversaryRejects
        Adversary adv = new Adversary(adversaryRejects);

        // give the contract some funds by sending from the owner (the test runner is the deployer/owner)
        if (funding > 0) {
            vm.deal(address(this), funding);
            // msg.sender is test contract which equals c.owner since c was deployed in setUp by this test
            c.sendMoney{value: 0}(address(0), 0); // harmless; exercising no-op path (keeps shape)
            // send funds directly to c using low-level call to its receive
            (bool ok,) = address(c).call{value: funding}("");
            require(ok);
        }

        // record balance before sending to adversary
        uint256 before = address(c).balance;

        // owner calls sendMoney to adversarial recipient with entire contract balance
        // use prank to ensure msg.sender is owner (the test contract deployed C, so it's owner)
        vm.prank(address(this));
        // attempt to route full balance out; this may revert in reference if recipient reverts
        bool callSucceeded;
        try c.sendMoney(address(adv), before) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // Now, the universal property for the reference: after the above, owner can always withdraw the remaining contract balance
        // We observe this by attempting withdraw(address(c).balance) and seeing it does not revert (i.e., succeeds).
        // We'll perform the withdraw under a try/catch and assert that it succeeds for the reference contract.
        bool withdrawOk;
        vm.prank(address(this));
        try c.withdraw(address(c).balance) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // Single assertion: in the reference implementation withdraw must always succeed for all inputs; the mutant that uses .send may fail for some inputs
        assertTrue(withdrawOk);
    }
}

// adversarial recipient: either accepts Ether or reverts in receive()
contract Adversary {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("reject");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive: deposit some ether into c, then attempt withdraw by a caller (this contract)
    // The rule: if this contract is not the owner (msg.sender != c.owner()), then calling withdraw must not decrease address(c).balance

    // single public function holding all logic
    function checkWithdrawBehavior(uint depositAmount, uint withdrawAmount) public payable {
        // require we have ether to send into c for the deposit
        require(address(this).balance >= depositAmount);
        // deposit into c via receive() by sending ether
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        uint before = address(c).balance;

        // ensure caller of withdraw will be this contract (not the original owner in P)
        // If this contract is not owner, in P withdraw should revert due to onlyOwner; in M it will succeed and reduce balance
        // Attempt to withdraw withdrawAmount (can succeed or revert)
        // This is a state-changing call and must be a top-level statement
        // We call and capture whether it reverted by using low-level call
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));

        uint after = address(c).balance;

        // If this contract is NOT the owner, then withdraw must NOT have succeeded in reducing the contract balance.
        // We express that: if c.owner() != address(this) then either withdraw call failed (ok == false) or balance did not decrease (after >= before - withdrawAmount)
        // Simplify to: if not owner then after >= before - withdrawAmount
        // To keep a single assert, we include the ownership check into the formula.
        address owner = c.owner();
        // assert the distinguishing property
        assert(owner == address(this) || after >= before - withdrawAmount);
    }

    // allow the test contract to receive ether for funding deposits
    receive() external payable {}
}

