// Helper contracts
contract Reverter {
    fallback() external payable { revert("no"); }
    receive() external payable { revert("no"); }
}

// Owner-like contract that reverts on receive and can deploy C and call withdraw
contract RevertingOwner {
    function deployC() external returns (C) {
        C c = new C();
        // after deployment, owner is address(this) (RevertingOwner)
        return c;
    }
    function callWithdraw(C c, uint256 amt) external {
        // call withdraw as this contract (the owner)
        c.withdraw(amt);
    }
}

